// gbaplanner country holidays: read-only lookup into the table generated by
// tools/holidays/generate.py (src/holidays/holiday_data.c).
//
// Countries are numbered 0..holidays_country_count()-1; 0 is "No country"
// (never has holidays), 1..34 follow the Settings order (Austria ... Japan).
// Years HOLIDAYS_FIRST_YEAR..HOLIDAYS_LAST_YEAR (Gregorian), months 1..12,
// days 1..31. Arguments out of range give 0 holidays, never a crash.
//
// No heap, no static state, no exceptions/RTTI; all data is const (ROM).
// Names are UTF-8 strings in ROM (a few contain accented letters).
#ifndef GBAPLANNER_HOLIDAYS_H
#define GBAPLANNER_HOLIDAYS_H

#include <stdint.h>

#define HOLIDAYS_FIRST_YEAR 1900
#define HOLIDAYS_LAST_YEAR 2200
#define HOLIDAYS_NO_COUNTRY 0

struct HolidayItem
{
    const char* name;  // English name, UTF-8, points into ROM
};

// Number of entries for the Settings row, including "No country" (35).
int holidays_country_count();

// "No country", "Austria", ..., "Japan". nullptr when out of range.
const char* holidays_country_name(int country);

// ISO 3166 code ("AT", ..., "JP"); "" for No country; nullptr out of range.
const char* holidays_country_code(int country);

// Holidays on one day. Writes up to `max` items to `out` (out may be nullptr
// when max is 0) and returns the total number of holidays on that day (may be
// larger than max). Several holidays on one day are separate items.
int holidays_on_day(int country, int year, int month, int day, HolidayItem* out, int max);

// Holidays of one month for the calendar dots: counts[d - 1] = number of
// holidays on day d (counts must have room for 31 entries; days past the end
// of the month are set to 0). `day_mask` (may be nullptr) gets bit d - 1 set
// for every day with at least one holiday. Returns the total number of
// holidays in the month.
int holidays_in_month(int country, int year, int month, uint8_t counts[31], uint32_t* day_mask);

#endif
